from fastmcp import Server
import json
import sys
import asyncio

server = Server("config-server")

@server.resource("data://config")
def get_config():
    """Returns a static configuration dictionary"""
    config = {
        "name": "example",
        "version": "1.0.0",
        "settings": {
            "debug": True,
            "timeout": 30
        }
    }
    return json.dumps(config)

if __name__ == "__main__":
    asyncio.run(server.run(stdin=sys.stdin, stdout=sys.stdout))
